const item = $input.first().json || {};
const headers = item.headers || {};
const body = item.body || {};
const host = String(headers.host || headers.Host || '').toLowerCase();
const forwardedHost = String(headers['x-forwarded-host'] || headers['X-Forwarded-Host'] || '').toLowerCase();
const authHeader = String(headers.authorization || headers.Authorization || '');
const token = String(headers['x-ql-sync-token'] || headers['X-QL-Sync-Token'] || authHeader.replace(/^Bearer\s+/i, '') || '');
const expectedHash = '2b1af5eccaafa1ec6b1bdb820c7bcea416bd4d07e98891b4517b6bca2d6d571e';

function sha256(ascii) {
  function rightRotate(value, amount) { return (value >>> amount) | (value << (32 - amount)); }
  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  const lengthProperty = 'length';
  let i, j;
  let result = '';
  const words = [];
  const asciiBitLength = ascii[lengthProperty] * 8;
  const hash = sha256.h = sha256.h || [];
  const k = sha256.k = sha256.k || [];
  let primeCounter = k[lengthProperty];
  const isComposite = {};
  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
    }
  }
  ascii += '\x80';
  while (ascii[lengthProperty] % 64 - 56) ascii += '\x00';
  for (i = 0; i < ascii[lengthProperty]; i++) {
    j = ascii.charCodeAt(i);
    if (j >> 8) return '';
    words[i >> 2] |= j << ((3 - i) % 4) * 8;
  }
  words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
  words[words[lengthProperty]] = (asciiBitLength);
  for (j = 0; j < words[lengthProperty];) {
    const w = words.slice(j, j += 16);
    const oldHash = hash.slice(0);
    for (i = 0; i < 64; i++) {
      const w15 = w[i - 15], w2 = w[i - 2];
      const a = hash[0], e = hash[4];
      const temp1 = hash[7]
        + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
        + ((e & hash[5]) ^ ((~e) & hash[6]))
        + k[i]
        + (w[i] = (i < 16) ? w[i] : (
          w[i - 16]
          + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
          + w[i - 7]
          + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
        ) | 0);
      const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
        + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash.pop();
      hash.unshift((temp1 + temp2) | 0);
      hash[4] = (hash[4] + temp1) | 0;
    }
    for (i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
  }
  for (i = 0; i < 8; i++) {
    for (j = 3; j + 1; j--) {
      const b = (hash[i] >> (j * 8)) & 255;
      result += ((b < 16) ? '0' : '') + b.toString(16);
    }
  }
  return result;
}

const tokenOk = Boolean(token) && sha256(token) === expectedHash;
const internalHost = /^(localhost|127\.0\.0\.1|n8n)(:|$)/.test(host)
  || /^(localhost|127\.0\.0\.1|n8n)(:|$)/.test(forwardedHost);

if (!tokenOk && !internalHost) {
  throw new Error('[AUTH OUTBOUND] unauthorized quicklink-lead-inbound');
}

const SAFETY_REAL_SENDS_ENABLED = false;
function normalizeDigits(value) {
  return String(value || '').replace(/\D/g, '');
}
const outboundPhoneDigits = normalizeDigits(body.phone || body.telefono_1 || body.to_phone || '');
const requestSource = String(body.source || '');
const outboundDispatcherAllowed = internalHost
  && requestSource === 'outbound-dispatcher'
  && outboundPhoneDigits.length >= 9
  && outboundPhoneDigits.length <= 15;
const panelBatchKey = String(body.batch_key || '');
const panelLeadId = String(body.lead_id || '');
const panelRequestId = String(body.request_id || '');
const panelOperatorAllowed = internalHost
  && tokenOk
  && requestSource === 'panel-operador'
  && /^ops05:\d+$/.test(panelBatchKey)
  && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(panelLeadId)
  && panelRequestId === panelBatchKey + ':' + panelLeadId
  && outboundPhoneDigits.length >= 9
  && outboundPhoneDigits.length <= 15;
if (!SAFETY_REAL_SENDS_ENABLED && !outboundDispatcherAllowed && !panelOperatorAllowed) {
  throw new Error('[SAFETY OUTBOUND] real_sends_disabled_while_resolving_error');
}

return [{ json: {
  ...item,
  body,
  outbound_intake_auth: tokenOk ? 'token' : 'internal',
  outbound_dispatcher_guard: outboundDispatcherAllowed ? 'allowlisted_internal_dispatcher' : (panelOperatorAllowed ? 'panel_operator_tracking' : 'safety_disabled'),
  outbound_intake_guard: outboundDispatcherAllowed ? 'allowlisted_internal_dispatcher' : (panelOperatorAllowed ? 'panel_operator_tracking' : 'safety_disabled'),
} }];

const body = $json.body || {};
const phone = String(body.phone || body.telefono_1 || $json.phone || $json.telefono_1 || '').trim();
const marca = String(body.marca || $json.marca || 'KIA').toUpperCase();
const quicklinkId = body.quicklink_id || $json.quicklink_id || null;
const defaultCountryCode = String($('Set Campaign Config').first().json.default_country_code || '').replace(/\D/g, '');
const explicitCountryCode = String(
  body.country_code
  || body.codigo_pais
  || $json.country_code
  || $json.codigo_pais
  || ''
).replace(/\D/g, '');
const KNOWN_COUNTRY_CODES = ['593', '52', '55', '57'];

function inferCountryCode(digits, explicitCc) {
  if (explicitCc) return explicitCc;
  const match = KNOWN_COUNTRY_CODES.find(cc => String(digits || '').startsWith(cc));
  return match || defaultCountryCode;
}

function normalizeWaPhone(raw, explicitCc) {
  let p = String(raw || '').trim();
  if (!p) return '';
  if (p.startsWith('+')) return p.replace(/\D/g, '');
  p = p.replace(/\D/g, '');
  if (p.startsWith('00')) p = p.slice(2);
  const inferred = KNOWN_COUNTRY_CODES.find(cc => p.startsWith(cc));
  const cc = explicitCc || inferred || defaultCountryCode;
  if (cc && !p.startsWith(cc) && !inferred) return cc + p.replace(/^0+/, '');
  return p;
}

const toPhone = normalizeWaPhone(phone, explicitCountryCode);
const countryCode = inferCountryCode(toPhone, explicitCountryCode);
return [{ json: {
  phone,
  marca,
  quicklink_id: quicklinkId,
  lead_id: body.lead_id || $json.lead_id || null,
  country_code: countryCode,
  to_phone: toPhone,
  source: String(body.source || $json.source || 'outbound-intake'),
  batch_key: String(body.batch_key || $json.batch_key || ''),
  request_id: String(body.request_id || $json.request_id || ''),
} }];

// Normalize incoming data into array of campaign recipients
const items = $input.all();

const recipients = items.flatMap(item => {
  const d = item.json;
  if (Array.isArray(d.recipients)) {
    return d.recipients.map(r => ({ json: { ...d, ...r } }));
  }
  return [{ json: d }];
});

return recipients.length > 0 ? recipients : [{ json: items[0]?.json || {} }];

// Aggregate Meta API acceptance from the completed send/log path.
// A webhook 202 is valid only when all expected Meta message IDs are present.
const inputItems = $input.all();
let sourceItems = inputItems;
try {
  const loggedItems = $('Log Campaign to Chatwoot').all();
  if (Array.isArray(loggedItems) && loggedItems.length) sourceItems = loggedItems;
} catch (e) {}

const rows = sourceItems.map(item => item.json || {}).filter(row => Object.keys(row).length);
const base = rows[0] || inputItems[0]?.json || {};
const expectedPerRecipient = Math.max(1, Number(base.expected_messages || (Array.isArray(base.template_names_used) ? base.template_names_used.length : 2)) || 2);
const totalRecipients = Math.max(1, rows.length || inputItems.length || 1);
const expectedMessages = expectedPerRecipient * totalRecipients;
const allMessages = rows.flatMap(row => Array.isArray(row.messages) ? row.messages : []);
const acceptedMessages = allMessages.filter(message => {
  const id = message?.id || message?.message_id || message?.meta_message_id || null;
  const status = String(message?.message_status || message?.status || '').toLowerCase();
  return Boolean(id) && ['accepted', 'sent', 'delivered', 'read'].includes(status);
});
const messageIds = [...new Set(acceptedMessages.map(message => message.id || message.message_id || message.meta_message_id).filter(Boolean))];
const metaAcceptedComplete = messageIds.length >= expectedMessages;

return [{ json: {
  ...base,
  request_id: base.request_id || null,
  batch_key: base.batch_key || null,
  source: base.source || 'outbound-intake',
  campaign_summary: {
    status: metaAcceptedComplete ? 'meta_accepted' : 'meta_not_accepted',
    total_recipients: totalRecipients,
    expected_messages: expectedMessages,
    accepted_count: messageIds.length,
    message_ids: messageIds,
    meta_accepted_complete: metaAcceptedComplete,
    incomplete_reason: metaAcceptedComplete ? null : 'meta_message_ids_missing',
    completed_at: new Date().toISOString(),
  },
} }];

async function __salesProdHttpRequest(opts) {
  if (opts && String(opts.url || '').includes('/rest/v1/')) {
    opts = {
      ...opts,
      headers: {
        ...(opts.headers || {}),
        'Accept-Profile': 'sales_prod',
        'Content-Profile': 'sales_prod',
      },
    };
  }
  return this.helpers.httpRequest(opts);
}

const conv = $input.first()?.json;
const lead = $('Postgres - Buscar Lead').first().json;
const norm = $('Guardar Conversacion Supabase').first().json;

if (!lead?.lead_id || !conv?.conv_id) {
  throw new Error('[OUTBOUND GUARD] Missing lead_id=' + (lead?.lead_id || null) + ' or conv_id=' + (conv?.conv_id || null));
}

// Outbound no crea lead_memory por defecto: lo upsert-eamos aqui para que
// cualquier respuesta del cliente entre por el AI (no por el flujo de lead frio).
// La clave sigue siendo phone, pero se vincula al lead/conv seleccionados para evitar duplicados.
try {
  const SB_URL = 'https://quicklink.spb.aigentss.cloud';
  const SB_KEY = '${REDACTED_JWT}';
  const toPhone = String(norm?.to_phone || '').replace(/^\+/, '');
  if (toPhone) {
    const phoneE164 = '+' + toPhone;
    const memHeaders = { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json', Prefer: 'return=minimal' };
    const resetBody = {
      lead_id: lead.lead_id,
      conversation_id: conv.conv_id,
      conversation_state: 'CONTACTED_1',
      source: 'outbound',
      outbound_sequence_status: 'ACTIVE',
      customer_engaged: false,
      followup_at: null,
      last_inbound_message_at: null,
      asesor_requerido: false,
      turn_count: 0
    };
    // PATCH explicito: resetea estado stale (ej. TRANSFERIDO_HUMANO) al enviar nuevo CONTACTED_1.
    await __salesProdHttpRequest.call(this, {
      method: 'PATCH',
      url: SB_URL + '/rest/v1/lead_memory?phone=eq.' + encodeURIComponent(phoneE164),
      headers: memHeaders,
      body: JSON.stringify(resetBody),
      ignoreHttpStatusErrors: true,
    }).catch(() => null);
    // Si no existia registro, crear uno nuevo.
    await __salesProdHttpRequest.call(this, {
      method: 'POST',
      url: SB_URL + '/rest/v1/lead_memory',
      headers: { ...memHeaders, Prefer: 'resolution=ignore-duplicates,return=minimal' },
      body: JSON.stringify({ phone: phoneE164, ...resetBody }),
      ignoreHttpStatusErrors: true,
    }).catch(() => null);
  }
} catch (e) { /* no-fatal: no bloquear el envio outbound */ }

return [{ json: {
  lead_found: true,
  lead_id: lead.lead_id,
  conv_id: conv.conv_id,
  conversation_is_new: conv.is_new === true,
  lead_linked: conv.lead_linked === true,
  request_id: norm.request_id || null,
  batch_key: norm.batch_key || null,
  source: norm.source || 'outbound-intake',
  quicklink_id: lead.quicklink_id,
  nombre_cliente: lead.nombre_cliente,
  modelo: lead.modelo,
  marca: lead.marca,
  to_phone: norm.to_phone,
  country_code: norm.country_code,
  meta_phone_number_id: '1114673978398967',
  meta_access_token: 'EAAN8geA7G2cBRuGWjXc6HC1iVPTu1OXXjoz4MeRvl0lfOwBnrLtfFrRyM8KaCbHflJEejlZCGndo0wBKhUuVbK9tDivfLnZCTqXfKk6weNP1d5GXZBTlhZBqrkXZAG8hwPRbD4ZAUuzRPAjofZCFKpM6NmasbxgP0YJTQYM5JhDTXfWQ8t0a5HMz6yYMB7ZCI05rSwZDZD',
  mensajes_bienvenida: lead.mensajes_bienvenida || [],
  servicio_marca: lead.servicio_marca || ''
} }];

// CRIS v2.4 — Preparar Mensaje Bienvenida — CTA neutral único
const marca = String($json.marca || 'KIA').toUpperCase();
function toTitleCase(s) { return String(s || '').toLowerCase().replace(/ w/g, c => c.toUpperCase()); }
const nombre = toTitleCase($json.nombre_cliente || 'estimado/a cliente');
const modelo = toTitleCase($json.modelo || 'su vehículo');
const marcaNombre = marca === 'HYUNDAI' ? 'Hyundai' : 'KIA';

const mensaje = [
  '¡Hola ' + nombre + '! Soy Cris, asesora comercial de ' + marcaNombre + '.',
  'Quería felicitarle por su nuevo ' + modelo + '.',
  '¿Le interesa conocer una forma de tener más seguridad y control sobre su ' + modelo + '?',
  '✅ Sí, quiero saber más',
  '❌ No por el momento'
].join('\n');

return [{
  json: {
    ...$json,
    mensaje_bienvenida_final: mensaje,
    mensaje_bienvenida_escaped: JSON.stringify(mensaje).slice(1, -1),
    variante: 'gancho_q1_neutral'
  }
}];

// Build WhatsApp template payloads.
//
// FASE 2 opt-in/opt-out (PLAN_CRIS04_OPT_IN_OPT_OUT.md, decision A + A1):
//   consent_status = OPTED_IN -> secuencia de bienvenida MARKETING (intro + CTA)
//   cualquier otro            -> plantilla de opt-in UTILITY, UN SOLO envio
//
// El gate de la Fase 1 ('IF - Consent Permite Envio') ya descarto OPTED_OUT y
// PENDING antes de llegar aca, asi que 'cualquier otro' es en la practica UNKNOWN.

const d = $('Preparar Mensaje Bienvenida').first().json;
const consent = String($('Postgres - Buscar Lead').first().json.consent_status || 'UNKNOWN').toUpperCase();
const optinMode = consent !== 'OPTED_IN';

const recipientPhone = $('Code - Armar Output').first().json.to_phone
  || d.contacts?.[0]?.input || d.phone || d.telefono || d.wa_id || d.whatsapp;

function toTitleCase(s) { return String(s||'').toLowerCase().replace(/\b\w/g, c => c.toUpperCase()); }
const marca      = (d.marca || '').toUpperCase();
const nombreTC   = toTitleCase(d.nombre_cliente || d.nombre || 'Cliente');
const modeloTC   = toTitleCase(d.modelo || 'su vehículo');

// Los modelos llegan como codigo comercial completo, p.ej.
//   'CRETA SU2 AC 1.5 5P 4X2 TM (FL)'  ->  'Creta'
//   'SOLUTO'                           ->  'Soluto'
// Verificado 2026-08-21: 156 de los 182 leads pendientes tienen el codigo
// largo. Mandarlo crudo produce "tu nuevo Creta Su2 Ac 1.5 5p 4x2 Tm (fl)".
// Solo se aplica a la rama de opt-in; la secuencia de bienvenida conserva su
// comportamiento historico hasta que se decida cambiarlo.
function nombreModelo(raw) {
  const s = String(raw || '').trim();
  if (!s) return 'su vehículo';
  const first = (s.split(/[\s/(\-]+/)[0] || s);
  return first.charAt(0).toUpperCase() + first.slice(1).toLowerCase();
}
const modeloCorto = nombreModelo(d.modelo);

if (marca !== 'KIA' && marca !== 'HYUNDAI') {
  throw new Error(`[GUARD BIENVENIDA] vehicle_brand inválido: "${marca}". lead_id=${d.lead_id} conv_id=${d.conv_id}`);
}

function buildPayload(tpl) {
  const template = {
    name: tpl.name,
    language: { code: tpl.lang },
  };
  const components = [];
  if (Array.isArray(tpl.params) && tpl.params.length) {
    components.push({ type: 'body', parameters: tpl.params });
  }
  if (Array.isArray(tpl.buttons) && tpl.buttons.length) {
    for (const btn of tpl.buttons) {
      components.push({
        type: 'button',
        sub_type: 'quick_reply',
        index: String(btn.index),
        parameters: [{ type: 'payload', payload: btn.payload }],
      });
    }
  }
  if (components.length) template.components = components;
  return {
    messaging_product: 'whatsapp',
    to: recipientPhone,
    type: 'template',
    template,
  };
}

// ===================== RAMA OPT-IN (Fase 2) =====================
// Plantilla UTILITY, neutral de marca, un unico envio. Los payloads de los
// botones tienen que coincidir EXACTO con BUTTON_RULES de CRIS-01 y con las
// ramas de la RPC claim_whatsapp_button_interaction (migracion V155).
if (optinMode) {
  const OPTIN = {
    name: 'quicklink_optin_ventas_v2',
    lang: 'es_EC',
    params: [{ type: 'text', text: nombreTC }, { type: 'text', text: modeloCorto }],
    buttons: [
      { index: 0, payload: 'optin_grant_v1' },
      { index: 1, payload: 'optin_deny_v1' },
    ],
  };
  const optinPayload = buildPayload(OPTIN);
  return [{
    json: {
      ...d,
      optin_mode: true,
      consent_status: consent,
      template_step: 'optin',
      template_name_used: OPTIN.name,
      template_name_final: OPTIN.name,
      template_name_intro: OPTIN.name,
      template_name_cta: null,
      template_names_used: [OPTIN.name],
      template_payload: optinPayload,
      template_payload_intro: optinPayload,
      template_payload_cta: null,
      template_variant: null,
      template_variant_strategy: 'optin_single',
    }
  }];
}

// ===================== RAMA BIENVENIDA (solo OPTED_IN) =====================
const BIENVENIDA = {
  KIA: [
    {
      variant: 'v1',
      aliases: ['kia_bienvenida_intro_v4_1', 'kia_bienvenida_cta_v4_1'],
      intro: { name: 'kia_bienvenida_intro_v4_1', lang: 'es', params: [{ type:'text', text:nombreTC }, { type:'text', text:modeloTC }] },
      cta:   { name: 'kia_bienvenida_cta_v4_1',   lang: 'es', params: [] },
    },
    {
      variant: 'v2',
      aliases: ['kia_bienvenida_intro_v4_2', 'kia_bienvenida_cta_v4_2'],
      intro: { name: 'kia_bienvenida_intro_v4_2', lang: 'es', params: [{ type:'text', text:nombreTC }, { type:'text', text:modeloTC }] },
      cta:   { name: 'kia_bienvenida_cta_v4_2',   lang: 'es', params: [] },
    },
    {
      variant: 'v3',
      aliases: ['kia_bienvenida_intro_v4_3', 'kia_bienvenida_cta_v4_3'],
      intro: { name: 'kia_bienvenida_intro_v4_3', lang: 'es', params: [{ type:'text', text:nombreTC }, { type:'text', text:modeloTC }] },
      cta:   { name: 'kia_bienvenida_cta_v4_3',   lang: 'es', params: [] },
    },
  ],
  HYUNDAI: [
    {
      variant: 'v1',
      aliases: ['hyundai_bienvenida_intro_v4_1', 'hyundai_bienvenida_cta_v4_1'],
      intro: { name: 'hyundai_bienvenida_intro_v4_1', lang: 'es', params: [{ type:'text', text:nombreTC }, { type:'text', text:modeloTC }] },
      cta:   { name: 'hyundai_bienvenida_cta_v4_1',   lang: 'es', params: [] },
    },
    {
      variant: 'v2',
      aliases: ['hyundai_bienvenida_intro_v4_2', 'hyundai_bienvenida_cta_v4_2'],
      intro: { name: 'hyundai_bienvenida_intro_v4_2', lang: 'es', params: [{ type:'text', text:nombreTC }, { type:'text', text:modeloTC }] },
      cta:   { name: 'hyundai_bienvenida_cta_v4_2',   lang: 'es', params: [] },
    },
    {
      variant: 'v3',
      aliases: ['hyundai_bienvenida_intro_v4_3', 'hyundai_bienvenida_cta_v4_3'],
      intro: { name: 'hyundai_bienvenida_intro_v4_3', lang: 'es', params: [{ type:'text', text:nombreTC }, { type:'text', text:modeloTC }] },
      cta:   { name: 'hyundai_bienvenida_cta_v4_3',   lang: 'es', params: [] },
    },
  ],
};

const opciones = (BIENVENIDA[marca] || []).filter(o => !(marca === 'HYUNDAI' && o.variant === 'v1'));
if (!opciones.length) throw new Error('[GUARD CATÁLOGO] No hay templates de bienvenida para ' + marca);

const override = d.template_name || d.templateName || '';
const leadId = d.lead_id || null;
const convId = d.conv_id || null;
const variantSeed = String(convId || leadId || d.to_phone || d.phone || d.telefono || '');
const variantPersisted = Boolean(variantSeed);
const variantPersistenceError = variantSeed ? null : 'missing_stable_seed';
let selected = null;

function stableVariantIndex(seed, length) {
  let hash = 2166136261;
  for (const char of String(seed || '')) {
    hash ^= char.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) % length;
}

if (override) {
  selected = opciones.find(o => o.variant === override || o.aliases.includes(override));
  if (!selected) throw new Error('[GUARD CATÁLOGO] Template "' + override + '" no existe en bienvenida split. lead_id=' + d.lead_id);
}

if (!selected) selected = opciones[stableVariantIndex(variantSeed, opciones.length)];

if (!selected.intro.name.startsWith(marca.toLowerCase()) || !selected.cta.name.startsWith(marca.toLowerCase())) {
  throw new Error(`[GUARD FINAL] Bienvenida split no corresponde a marca "${marca}". lead_id=${d.lead_id}`);
}

const introPayload = buildPayload(selected.intro);
const ctaPayload = buildPayload({
  ...selected.cta,
  buttons: [
    { index: 0, payload: 'gancho_si_gancho_q1_neutral' },
    { index: 1, payload: 'gancho_no_gancho_q1_neutral' },
  ],
});
const templateNames = [selected.intro.name, selected.cta.name];
const common = {
  ...d,
  optin_mode: false,
  consent_status: consent,
  template_variant: selected.variant,
  template_name_intro: selected.intro.name,
  template_name_cta: selected.cta.name,
  template_name_final: selected.cta.name,
  template_names_used: templateNames,
  template_payload_intro: introPayload,
  template_payload_cta: ctaPayload,
  template_variant_persisted: variantPersisted,
  template_variant_persistence_error: variantPersistenceError,
  template_variant_strategy: 'deterministic_seed',
};

return [{
  json: {
    ...common,
    template_step: 'intro',
    template_name_used: selected.intro.name,
    template_payload: introPayload,
  }
}];

// Prepare Chatwoot campaign logging data. Chatwoot calls run in HTTP nodes using the Chatwoot API credential.
const d = $('Prepare Template Payload').first().json;

const CW_URL = 'http://chatwoot:3000';
const CW_ACCOUNT = 2;
const CW_INBOX = 2;

const rawPhone = String(d.phone || d.telefono || d.to_phone || '').trim();
const nombre = d.nombre_cliente || d.nombre || 'Cliente';
const modelo = d.modelo || '';
const marca = (d.marca || 'KIA').toUpperCase();
const templateName = d.template_name_final || d.template_name_used || d.template_name || d.templateName || 'template';
// FASE 2: la rama opt-in envia una sola plantilla UTILITY, no la bienvenida.
const campaignStep = d.optin_mode === true ? 'Contacto 0 / Opt-in' : 'Contacto 1 / Bienvenida';

const introResp = $('Send WhatsApp Template').first()?.json || {};
// FASE 2: en la rama opt-in el nodo de CTA NUNCA se ejecuta, y en n8n
// referenciar un nodo no ejecutado lanza error (el ?. no protege de eso
// porque el throw ocurre en $(...), antes del acceso a .json).
const isOptinRun = d.optin_mode === true;
let ctaResp = {};
if (!isOptinRun) {
  try { ctaResp = $('Send WhatsApp CTA Template').first()?.json || {}; } catch (e) { ctaResp = {}; }
  if (!Object.keys(ctaResp).length) ctaResp = $input.first()?.json || {};
}
const waResponses = [introResp, ctaResp].filter(resp => resp && Object.keys(resp).length);
const waMessages = waResponses.flatMap(resp => Array.isArray(resp?.messages) ? resp.messages : []);
const expectedMessages = Array.isArray(d.template_names_used) ? d.template_names_used.length : 1;
const sendOk = waMessages.length >= expectedMessages
  && waMessages.every(message => String(message?.message_status || '').toLowerCase() === 'accepted');
const sendStatus = sendOk ? 'Aceptado por Meta' : 'Sin confirmacion';

function digits(value) {
  return String(value || '').replace(/\D/g, '');
}

function normalizeE164(value) {
  let p = digits(value);
  if (!p) return '';
  if (p.startsWith('593') || p.startsWith('57') || p.startsWith('55') || p.startsWith('52')) return '+' + p;
  if (p.startsWith('0') && p.length === 10) return '+593' + p.slice(1);
  if (p.length === 9 && p.startsWith('9')) return '+593' + p;
  return '+' + p;
}

function searchQuery(value) {
  const e164 = normalizeE164(value);
  const noPlus = e164.replace(/^\+/, '');
  if (noPlus.startsWith('593')) return noPlus.slice(3);
  return noPlus || digits(value);
}

const phoneE164 = normalizeE164(rawPhone || d.to_phone);
const noteContent = [
  'Campaign Template aceptado por Meta API',
  '',
  'Flujo: ' + campaignStep,
  'Cliente: ' + nombre,
  'Telefono: ' + (phoneE164 || rawPhone),
  'Vehiculo: ' + [marca, modelo].filter(Boolean).join(' '),
  'Template: ' + templateName,
  'Estado: ' + sendStatus,
  'Hora: ' + new Date().toLocaleString('es-EC', { timeZone: 'America/Guayaquil' })
].join('\n');

const activityContent = [
  'CRIS outbound Meta API: ' + campaignStep,
  'Proyeccion visible en Chatwoot; el template real fue enviado por WhatsApp Cloud API.',
  'Template Meta: ' + templateName,
  'Cliente: ' + nombre,
  'Telefono: ' + (phoneE164 || rawPhone),
  'Vehiculo: ' + [marca, modelo].filter(Boolean).join(' '),
  'Estado Meta: ' + sendStatus
].join('\n');

return [{ json: {
  ...d,
  messages: waMessages,
  cw_url: CW_URL,
  cw_account: CW_ACCOUNT,
  cw_inbox: CW_INBOX,
  cw_search_query: searchQuery(rawPhone || d.to_phone),
  raw_phone: rawPhone,
  phone_e164: phoneE164,
  nombre,
  modelo,
  marca,
  template_name_chatwoot: templateName,
  campaign_step: campaignStep,
  send_status_chatwoot: sendStatus,
  note_content: noteContent,
  activity_content: activityContent,
} }];

// Prepare the CTA template only after the intro HTTP send has completed.
const d = $('Prepare Template Payload').first().json;
const introResponse = $input.first()?.json || {};

if (!d.template_payload_cta || !d.template_name_cta) {
  throw new Error('[GUARD BIENVENIDA CTA] Missing CTA payload from Prepare Template Payload');
}

return [{
  json: {
    ...d,
    intro_meta_response: introResponse,
    template_step: 'cta',
    template_name_used: d.template_name_cta,
    template_payload: d.template_payload_cta,
  }
}];

const base = $('CW - Prepare Campaign Log').first().json;
const searchResp = $input.first().json || {};

function digits(value) {
  return String(value || '').replace(/\D/g, '');
}
function contactsFrom(resp) {
  if (Array.isArray(resp)) return resp;
  if (Array.isArray(resp?.payload)) return resp.payload;
  if (Array.isArray(resp?.payload?.contacts)) return resp.payload.contacts;
  if (Array.isArray(resp?.data?.payload)) return resp.data.payload;
  if (Array.isArray(resp?.contacts)) return resp.contacts;
  if (resp?.id) return [resp];
  if (resp?.payload?.id) return [resp.payload];
  if (resp?.payload?.contact?.id) return [resp.payload.contact];
  if (resp?.contact?.id) return [resp.contact];
  return [];
}

const contacts = contactsFrom(searchResp);
const wanted = digits(base.phone_e164).slice(-9);
const exact = contacts.find(c => digits(c.phone_number).endsWith(wanted)) || contacts[0] || null;
const contactId = exact?.id || null;
const searchError = searchResp.error?.message || searchResp.error || null;

return [{ json: {
  ...base,
  cw_contact_id: contactId,
  cw_needs_create_contact: !contactId,
  cw_search_error: searchError ? String(searchError).slice(0, 200) : null,
} }];

const resolved = $('CW - Resolve Contact').first().json;
const input = $input.first().json || {};

function idFromContact(resp) {
  return resp?.id || resp?.payload?.id || resp?.payload?.contact?.id || resp?.contact?.id || resp?.data?.id || null;
}
function shortResp(resp) {
  return JSON.stringify(resp || {}).slice(0, 200);
}

let contactId = resolved.cw_contact_id || null;
let createError = null;
if (resolved.cw_needs_create_contact) {
  contactId = idFromContact(input);
  if (!contactId) createError = input.error?.message || input.error || shortResp(input);
}

return [{ json: {
  ...resolved,
  cw_contact_id: contactId || null,
  cw_create_error: createError ? String(createError).slice(0, 200) : null,
  cw_has_contact: Boolean(contactId),
} }];

const base = $('CW - Contact Ready').first().json;
const input = $input.first().json || {};

function idFromConversation(resp) {
  return resp?.id || resp?.payload?.id || resp?.payload?.conversation?.id || resp?.conversation?.id || resp?.data?.id || null;
}
function shortResp(resp) {
  return JSON.stringify(resp || {}).slice(0, 200);
}

const convId = idFromConversation(input);
const convError = convId ? null : (input.error?.message || input.error || shortResp(input));

return [{ json: {
  ...base,
  cw_conv_id: convId || null,
  cw_conv_error: convError ? String(convError).slice(0, 200) : null,
  cw_has_conversation: Boolean(convId),
} }];

const SB_URL = 'https://quicklink.spb.aigentss.cloud';
const SB_KEY = '${REDACTED_JWT}';
const H_SB = {
  apikey: SB_KEY,
  Authorization: 'Bearer ' + SB_KEY,
  'Content-Type': 'application/json',
  'Accept-Profile': 'sales_prod',
  'Content-Profile': 'sales_prod',
};

function safeNode(name) {
  try { return $(name).first().json || {}; } catch (e) { return {}; }
}
function idFromMessage(resp) {
  return resp?.id || resp?.payload?.id || resp?.payload?.message?.id || resp?.message?.id || resp?.data?.id || null;
}
function shortResp(resp) {
  return JSON.stringify(resp || {}).slice(0, 200);
}
function errFrom(resp) {
  const err = resp?.error?.message || resp?.error || resp?.message;
  return err ? String(err).slice(0, 200) : null;
}

const prepared = safeNode('CW - Prepare Campaign Log');
const contactReady = safeNode('CW - Contact Ready');
const convReady = safeNode('CW - Resolve Conversation');
const base = Object.keys(convReady).length ? convReady : (Object.keys(contactReady).length ? contactReady : prepared);

const contactId = base.cw_contact_id || null;
const cwConvId = base.cw_conv_id || null;
const waMessages = prepared.messages || base.messages || [];
const phoneE164 = base.phone_e164 || prepared.phone_e164 || '';

let cwResetError = null;
const resetResp = safeNode('HTTP - CW Reset Attributes');
if (cwConvId && Object.keys(resetResp).length) cwResetError = errFrom(resetResp);

let noteError = null;
let noteId = null;
let activityError = null;
let activityId = null;

if (!contactId) {
  return [{ json: { ...prepared, messages: waMessages, cw_note_status: 'contact_error', cw_search_error: base.cw_search_error || null, cw_create_error: base.cw_create_error || null, phone_e164: phoneE164 } }];
}

if (!cwConvId) {
  return [{ json: { ...prepared, messages: waMessages, cw_note_status: 'conv_error', cw_contact_id: contactId, cw_conv_error: base.cw_conv_error || null, phone_e164: phoneE164 } }];
}

const noteResp = safeNode('HTTP - CW Private Note');
noteId = idFromMessage(noteResp);
if (!noteId) noteError = errFrom(noteResp) || shortResp(noteResp);

const activityResp = safeNode('HTTP - CW Activity Message');
activityId = idFromMessage(activityResp);
if (!activityId) activityError = errFrom(activityResp) || shortResp(activityResp);

if (base.conv_id && contactId && cwConvId) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: SB_URL + '/rest/v1/rpc/upsert_chatwoot_ids',
      headers: H_SB,
      body: JSON.stringify({ p_conv_id: base.conv_id, p_contact_id: Number(contactId), p_cw_conv_id: Number(cwConvId) }),
      ignoreHttpStatusErrors: true
    });
  } catch (e) {}
}

if (phoneE164 && contactId && cwConvId) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: SB_URL + '/rest/v1/rpc/upsert_lead_memory_chatwoot_ids',
      headers: H_SB,
      body: JSON.stringify({ p_phone: phoneE164, p_chatwoot_contact_id: Number(contactId), p_chatwoot_conv_id: Number(cwConvId) }),
      ignoreHttpStatusErrors: true
    });
  } catch (e) {}
}

if (base.lead_id && base.conv_id) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: SB_URL + '/rest/v1/campaign_messages?lead_id=eq.' + base.lead_id + '&campaign_id=eq.' + base.conv_id,
      headers: { ...H_SB, Prefer: 'return=minimal' },
      body: JSON.stringify({ estado: 'ENVIADO', sent_at: new Date().toISOString() }),
      ignoreHttpStatusErrors: true
    });
  } catch (e) {}
}

return [{
  json: {
    ...prepared,
    ...base,
    messages: waMessages,
    cw_note_status: noteError ? 'note_error' : 'ok',
    cw_note_error: noteError,
    cw_note_id: noteId,
    cw_activity_status: activityError ? 'activity_error' : 'ok',
    cw_activity_error: activityError,
    cw_activity_id: activityId,
    cw_reset_error: cwResetError,
    cw_conv_id: cwConvId,
    cw_contact_id: contactId,
    phone_e164: phoneE164,
    chatwoot_credential_used: 'Chatwoot API',
  }
}];

// FASE 1 opt-in/opt-out (PLAN_CRIS04_OPT_IN_OPT_OUT.md).
// El contacto esta en OPTED_OUT: no se envia nada y el item vuelve al loop
// para que la campania siga con el resto de destinatarios.
//
// La auditoria va a la base y no al log de n8n porque este workflow tiene
// saveDataSuccessExecution: 'none' — un registro solo en la ejecucion se
// perderia. La escritura es NO FATAL (mismo patron que 'Code - Armar Output'):
// si la tabla no existe todavia (migracion V158 sin aplicar) o PostgREST
// falla, el skip igual ocurre. Bloquear el envio es lo critico; auditarlo no.
const lead = $('Postgres - Buscar Lead').first().json;
const norm = $('Guardar Conversacion Supabase').first().json;

const skip = {
  to_phone: norm.to_phone || null,
  lead_id: lead.lead_id || null,
  quicklink_id: lead.quicklink_id || null,
  marca: lead.marca || null,
  consent_status: lead.consent_status || null,
  skip_reason: String(lead.consent_status || '').toUpperCase() === 'PENDING'
    ? 'consent_pending_optin'
    : 'consent_opted_out',
  request_id: norm.request_id || null,
  batch_key: norm.batch_key || null,
  workflow: 'CRIS-04',
};

try {
  const SB_URL = 'https://quicklink.spb.aigentss.cloud';
  const SB_KEY = '${REDACTED_JWT}';
  await this.helpers.httpRequest({
    method: 'POST',
    url: SB_URL + '/rest/v1/lead_consent_skips',
    headers: {
      apikey: SB_KEY,
      Authorization: 'Bearer ' + SB_KEY,
      'Content-Type': 'application/json',
      'Content-Profile': 'sales_prod',
      Prefer: 'return=minimal',
    },
    body: JSON.stringify(skip),
    ignoreHttpStatusErrors: true,
  }).catch(() => null);
} catch (e) { /* no fatal: nunca bloquear el loop por la auditoria */ }

return [{ json: {
  skipped: true,
  ...skip,
  skipped_at: new Date().toISOString(),
} }];
